def matching_pairs(values, target):
    result = []
    for first in range(len(values)):
        for second in range(first + 1, len(values)):
            if values[first] + values[second] == target:
                result.append((first, second))
    return result

print(matching_pairs([2, 5, 2, 3], 5))
print(matching_pairs([2, 2], 4))
print(matching_pairs([5], 10))

def pair_indices(values, target):
    result = []
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] + values[j] == target:
                result.append((i, j))
    return result

print(pair_indices([1, 3, 2, 2], 4))
print(pair_indices([2, 2, 2], 4))
print(pair_indices([], 0))

def has_pair(values, target):
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] + values[j] == target:
                return True
    return False

print(has_pair([2], 4))
print(has_pair([2, 2], 4))
print(has_pair([-2, 5], 3))
print(has_pair([], 0))

def closest_pair(values, target):
    best = None
    best_error = None
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            error = abs(values[i] + values[j] - target)
            if best_error is None or error < best_error:
                best_error = error
                best = (i, j)
    return best

print(closest_pair([1, 4, 6], 8))
print(closest_pair([2, 2, 2], 5))
print(closest_pair([], 0))

def count_pairs(values, target):
    count = 0
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] + values[j] == target:
                count = count + 1
    return count

print(count_pairs([2, 2, 2], 4))
print(count_pairs([1, 3, 2, 2], 4))
print(count_pairs([], 0))
